PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, recovery TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS stays (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), data TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS stays_owner ON stays(user_id);
CREATE TABLE IF NOT EXISTS cities (slug TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'awaiting');
CREATE TABLE IF NOT EXISTS city_entries (id TEXT PRIMARY KEY, city_slug TEXT NOT NULL REFERENCES cities(slug), section TEXT NOT NULL, data TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS search_events (id INTEGER PRIMARY KEY, city_slug TEXT NOT NULL REFERENCES cities(slug), visitor TEXT NOT NULL, searched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS search_popularity ON search_events(searched_at, city_slug);
CREATE TABLE IF NOT EXISTS coverage_requests (city_slug TEXT PRIMARY KEY REFERENCES cities(slug), requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attempts (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS password_changes (user_id TEXT NOT NULL, changed_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS purchases (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), stay_id TEXT NOT NULL REFERENCES stays(id), amount INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', stripe_session TEXT UNIQUE, payment_intent TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS entitlements (purchase_id TEXT PRIMARY KEY REFERENCES purchases(id), user_id TEXT NOT NULL REFERENCES users(id), stay_id TEXT NOT NULL, expires_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS stripe_events (id TEXT PRIMARY KEY, received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS research_jobs (id TEXT PRIMARY KEY, cycle TEXT NOT NULL, city_slug TEXT NOT NULL, section TEXT NOT NULL, provider TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', result TEXT, error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(cycle, city_slug, section));
CREATE TABLE IF NOT EXISTS provider_usage (month TEXT NOT NULL, provider TEXT NOT NULL, used REAL NOT NULL DEFAULT 0, PRIMARY KEY(month,provider));
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), city_slug TEXT NOT NULL REFERENCES cities(slug), section TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS comment_likes (comment_id TEXT NOT NULL REFERENCES comments(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(comment_id,user_id));
CREATE TABLE IF NOT EXISTS comment_reports (comment_id TEXT NOT NULL REFERENCES comments(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(comment_id,user_id));
CREATE TABLE IF NOT EXISTS scenarios (id TEXT PRIMARY KEY, stay_id TEXT NOT NULL REFERENCES stays(id), user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, data TEXT NOT NULL);
